18	package org.apache.hadoop.ha;
19	
20	import java.io.BufferedWriter;
21	import java.io.File;
22	import java.io.FileOutputStream;
23	import java.io.IOException;
24	import java.io.OutputStreamWriter;
25	import java.net.InetSocketAddress;
26	import java.nio.charset.StandardCharsets;
27	
28	import org.apache.hadoop.conf.Configured;
29	import org.apache.hadoop.util.StringUtils;
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	
33	/**
34	 * Fencer method that uses PowerShell to remotely connect to a machine and kill
35	 * the required process. This only works in Windows.
36	 *
37	 * The argument passed to this fencer should be a unique string in the
38	 * "CommandLine" attribute for the "java.exe" process. For example, the full
39	 * path for the Namenode: "org.apache.hadoop.hdfs.server.namenode.NameNode".
40	 * The administrator can also shorten the name to "Namenode" if it's unique.
41	 */
42	public class PowerShellFencer extends Configured implements FenceMethod {
43	
44	  private static final Logger LOG = LoggerFactory.getLogger(PowerShellFencer
45	      .class);
46	
47	
48	  @Override
49	  public void checkArgs(String argStr) throws BadFencingConfigurationException {
50	    LOG.info("The parameter for the PowerShell fencer is " + argStr);
51	  }
52	
53	  @Override
54	  public boolean tryFence(HAServiceTarget target, String argsStr)
55	      throws BadFencingConfigurationException {
56	
57	    String processName = argsStr;
58	    InetSocketAddress serviceAddr = target.getAddress();
59	    String hostname = serviceAddr.getHostName();
60	
61	    // Use PowerShell to kill a remote process
62	    String ps1script = buildPSScript(processName, hostname);
63	    if (ps1script == null) {
64	      LOG.error("Cannot build PowerShell script");
65	      return false;
66	    }
67	
68	    // Execute PowerShell script
69	    LOG.info("Executing " + ps1script);
70	    ProcessBuilder builder = new ProcessBuilder("powershell.exe", ps1script);
71	    Process p = null;
72	    try {
73	      p = builder.start();
74	      p.getOutputStream().close();
75	    } catch (IOException e) {
76	      LOG.warn("Unable to execute " + ps1script, e);
77	      return false;
78	    }
79	
80	    // Pump logs to stderr
81	    StreamPumper errPumper = new StreamPumper(
82	        LOG, "fencer", p.getErrorStream(), StreamPumper.StreamType.STDERR);
83	    errPumper.start();
84	
85	    StreamPumper outPumper = new StreamPumper(
86	        LOG, "fencer", p.getInputStream(), StreamPumper.StreamType.STDOUT);
87	    outPumper.start();
88	
89	    // Waiting for the process to finish
90	    int rc = 0;
91	    try {
92	      rc = p.waitFor();
93	      errPumper.join();
94	      outPumper.join();
95	    } catch (InterruptedException ie) {
96	      LOG.warn("Interrupted while waiting for fencing command: " + ps1script);
97	      return false;
98	    }
99	
100	    return rc == 0;
101	  }
102	
103	  /**
104	   * Build a PowerShell script to kill a java.exe process in a remote machine.
105	   *
106	   * @param processName Name of the process to kill. This is an attribute in
107	   *                    CommandLine.
108	   * @param host Host where the process is.
109	   * @return Path of the PowerShell script.
110	   */
111	  private String buildPSScript(final String processName, final String host) {
112	    LOG.info(
113	        "Building PowerShell script to kill " + processName + " at " + host);
114	    String ps1script = null;
115	    BufferedWriter writer = null;
116	    try {
117	      File file = File.createTempFile("temp-fence-command", ".ps1");
118	      file.deleteOnExit();
119	      FileOutputStream fos = new FileOutputStream(file, false);
120	      OutputStreamWriter osw =
121	          new OutputStreamWriter(fos, StandardCharsets.UTF_8);
122	      writer = new BufferedWriter(osw);
123	
124	      // Filter to identify the Namenode process
125	      String filter = StringUtils.join(" and ", new String[] {
126	          "Name LIKE '%java.exe%'",
127	          "CommandLine LIKE '%" + processName+ "%'"});
128	
129	      // Identify the process
130	      String cmd = "Get-WmiObject Win32_Process";
131	      cmd += " -Filter \"" + filter + "\"";
132	      // Remote location
133	      cmd += " -Computer " + host;
134	      // Kill it
135	      cmd += " |% { $_.Terminate() }";
136	
137	      LOG.info("PowerShell command: " + cmd);
138	      writer.write(cmd);
139	      writer.flush();
140	
141	      ps1script = file.getAbsolutePath();
142	    } catch (IOException ioe) {
143	      LOG.error("Cannot create PowerShell script", ioe);
144	    } finally {
145	      if (writer != null) {
146	        try {
147	          writer.close();
148	        } catch (IOException ioe) {
149	          LOG.error("Cannot close PowerShell script", ioe);
150	        }
151	      }
152	    }
153	    return ps1script;
154	  }
155	}
